{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello यावर जी आपको rubber floorings की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "आपको कितने square feet चाहिए?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "वाकई मेजे से की थी ना।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "समझ रहे थे।"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "तो बाकी"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "हाँ एक तो।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अच्छा।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "आप कितने square feet की quantity लेना चाहेंगे?"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "approximate number बता दें ताकि मैं आपको seller से connect कर सकूं।"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "कितने square feet में?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "Ah."
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "A seller."
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "Sorry आपकी आवाज़ थोड़ी unclear आई।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आप कितने square feet की quantity लेना चाहेंगे?"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "approximate number बता दीजिए।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "क्या square का बताना है दिन का पूरा बताना पड़ेगा।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "[change] तो length।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "हाँ, ये आप अपनी जगह का पूरा length और चौड़ाई बता दीजिए जिससे मैं total square की।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "20 by 20."
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "बहुत बढ़िया आप बताइए।"
    },
    {
      "i": 24,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "बीस दिन से।"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "with दस है।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "आपकी जगह का total area 200 square feet हो गया।"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "अब thickness के लिए बताइए आपको 10 millimeters चाहिए ना?"
    }
  ]
}
